<?php  namespace App\Http\Controllers\Api;  use App\Http\Controllers\Controller; use App\Models\GameSetting;
use App\Models\OfferRedemption; use App\Models\RewardOffer; use App\Services\AchievementService; use Illuminate\Http\Request; use Illuminate\Support\Str;  class OfferController extends Controller {     public function __construct(private AchievementService $achievementService) {}     public function index(Request $request)     {         RewardOffer::expireEnded();         $query = RewardOffer::with(['business:id,name,type,district,address'])             ->active()             ->orderBy('created_at', 'desc');          if ($request->has('district') && $request->district) {             $query->whereHas('business', fn($q) => $q->where('district', $request->district));         }         if ($request->has('type') && $request->type) {             $query->where('offer_type', $request->type);         }          $offers = $query->limit(min((int) ($request->get('limit') ?: 50), 100))->get();          return response()->json([             'success' => true,             'offers' => $offers->map(fn($o) => $this->publicOffer($o)),         ]);     }      public function show(Request $request, $id)     {         $offer = RewardOffer::with('business')->active()->find($id);         if (!$offer) {             return response()->json(['success' => false, 'message' => 'Offer not found'], 404);         }         return response()->json(['success' => true, 'offer' => $this->publicOffer($offer)]);     }      public function claim(Request $request, $id)     {         RewardOffer::expireEnded();         $user = $request->user();          $offer = RewardOffer::active()->find($id);         if (!$offer) {             return response()->json(['success' => false, 'message' => 'Offer not found'], 404);         }          $existing = OfferRedemption::where('offer_id', $offer->id)->where('user_id', $user->id)->first();         if ($existing && $existing->status !== 'expired') {             return response()->json([                 'success' => false,                 'message' => 'You already claimed this offer.',                 'redemption' => $this->publicRedemption($existing),             ], 409);         }          if ($offer->usage_limit > 0 && $offer->used_count >= $offer->usage_limit) {             return response()->json(['success' => false, 'message' => 'This offer has reached its usage limit.'], 422);         }          if ($offer->price_xp > 0 && $user->total_xp < $offer->price_xp) {             return response()->json([                 'success' => false,                 'message' => 'Not enough XP. You need ' . $offer->price_xp . ' XP for this offer.',                 'balance' => $user->total_xp,             ], 422);         }          $code = 'RWD-' . strtoupper(Str::random(6));          $commissionPct = (float) GameSetting::getValue('offer_commission_percent', 10);         $offerValue = (float) $offer->value_npr;         $adminCommission = round($offerValue * $commissionPct / 100, 2);         $partnerEarnings = round($offerValue - $adminCommission, 2);          $redemption = OfferRedemption::create([             'offer_id' => $offer->id,             'user_id' => $user->id,             'code' => $code,             'status' => 'claimed',             'value_npr' => $offerValue,             'commission_percent' => $commissionPct,             'admin_commission' => $adminCommission,             'partner_earnings' => $partnerEarnings,             'claimed_at' => now(),         ]);          if ($offer->price_xp > 0) {             $this->achievementService->deductXp(                 $user,                 $offer->price_xp,                 'offer_purchase',                 'Redeemed offer: ' . $offer->title,             );         }          $offer->increment('used_count');          return response()->json([             'success' => true,             'message' => $offer->price_xp > 0                 ? 'Offer redeemed with ' . $offer->price_xp . ' XP! Show this code at the business.'                 : 'Offer claimed! Show this code at the business.',             'redemption' => $this->publicRedemption($redemption),             'balance' => $user->fresh()->total_xp,         ], 201);     }      public function my(Request $request)     {         $redemptions = OfferRedemption::with(['offer.business:id,name,type,district,address'])             ->where('user_id', $request->user()->id)             ->orderBy('created_at', 'desc')             ->get();          return response()->json([             'success' => true,             'redemptions' => $redemptions->map(fn($r) => $this->publicRedemption($r)),         ]);     }      public function available(Request $request)     {         $redemptions = OfferRedemption::with(['offer.business:id,name,type,district,address'])             ->where('user_id', $request->user()->id)             ->available()             ->orderBy('created_at', 'desc')             ->get();          return response()->json([             'success' => true,             'redemptions' => $redemptions->map(fn($r) => $this->publicRedemption($r)),         ]);     }      private function publicOffer(RewardOffer $offer): array     {         return [             'id' => $offer->id,             'title' => $offer->title,             'offer_type' => $offer->offer_type,             'discount_value' => $offer->discount_value,
            'value_npr' => (float) $offer->value_npr,             'price_xp' => $offer->price_xp,             'label' => $offer->label(),             'description' => $offer->description,             'terms' => $offer->terms,             'starts_at' => $offer->starts_at?->toIso8601String(),             'ends_at' => $offer->ends_at?->toIso8601String(),             'usage_limit' => $offer->usage_limit,             'used_count' => $offer->used_count,             'business' => $offer->business ? [                 'id' => $offer->business->id,                 'name' => $offer->business->name,                 'type' => $offer->business->type,                 'district' => $offer->business->district,                 'address' => $offer->business->address,             ] : null,         ];     }      private function publicRedemption(OfferRedemption $redemption): array     {         return [             'id' => $redemption->id,             'offer_id' => $redemption->offer_id,             'code' => $redemption->code,             'status' => $redemption->status,             'claimed_at' => $redemption->claimed_at?->toIso8601String(),             'used_at' => $redemption->used_at?->toIso8601String(),             'applied_at' => $redemption->applied_at?->toIso8601String(),             'consumed_at' => $redemption->consumed_at?->toIso8601String(),             'discount_amount' => $redemption->discount_amount,             'offer' => $redemption->offer ? $this->publicOffer($redemption->offer) : null,         ];     } }